@push('scripts')<script>
(() => {const stages=document.getElementById('stages'), transitions=document.getElementById('transitions'), start=document.getElementById('starting-stage'); if(!stages)return; const stageData=()=>[...stages.querySelectorAll('.stage-row')].map(r=>({code:r.querySelector('.stage-code').value,name:r.querySelector('.stage-name').value})).filter(x=>x.code); const options=(selected='')=>stageData().map(s=>`<option value="${s.code}" ${s.code===selected?'selected':''}>${s.name}</option>`).join(''); const refresh=()=>transitions.querySelectorAll('.transition-row').forEach(r=>{const f=r.querySelector('.from'),t=r.querySelector('.to'),fv=f.value,tv=t.value;f.innerHTML=options(fv);t.innerHTML=options(tv);f.value=fv;t.value=tv;}); const reindex=()=>{stages.querySelectorAll('.stage-row').forEach((r,i)=>r.querySelectorAll('[name]').forEach(e=>e.name=e.name.replace(/stages\[\d+\]/,`stages[${i}]`)));transitions.querySelectorAll('.transition-row').forEach((r,i)=>r.querySelectorAll('[name]').forEach(e=>e.name=e.name.replace(/transitions\[\d+\]/,`transitions[${i}]`)));refresh();}; stages.addEventListener('input',e=>{if(e.target.classList.contains('stage-name')){const r=e.target.closest('.stage-row');r.querySelector('.stage-code').value=e.target.value.trim().toUpperCase().replace(/[^A-Z0-9]+/g,'_').replace(/^_+|_+$/g,'');refresh();}}); stages.addEventListener('change',e=>{if(e.target.classList.contains('start-stage')&&e.target.value==='1'){start.value=e.target.closest('.stage-row').querySelector('.stage-code').value;stages.querySelectorAll('.start-stage').forEach(x=>{if(x!==e.target)x.value='0';});}}); stages.addEventListener('click',e=>{if(e.target.closest('.remove-stage')){e.target.closest('.stage-row').remove();if(!stageData().some(s=>s.code===start.value))start.value=stageData()[0]?.code||'';reindex();}}); transitions.addEventListener('click',e=>{if(e.target.closest('.remove-transition')){e.target.closest('.transition-row').remove();reindex();}}); document.getElementById('add-stage')?.addEventListener('click',()=>{const i=stages.querySelectorAll('.stage-row').length,r=document.createElement('div');r.className='card mb-3 stage-row';r.innerHTML=`<div class="card-header"><strong>New stage</strong></div><div class="card-body"><div class="form-row"><div class="form-group col-md-4"><label>Stage name</label><input name="stages[${i}][name]" class="form-control stage-name" required></div><div class="form-group col-md-3"><label>Code</label><input name="stages[${i}][code]" class="form-control stage-code" required></div><div class="form-group col-md-5"><label>Role</label><select name="stages[${i}][responsible_role_id]" class="form-control"><option value="">No fixed role</option>@foreach($roles as $role)<option value="{{ $role->id }}">{{ $role->name }}</option>@endforeach</select></div></div><div class="form-row"><div class="form-group col-md-4"><label>Assignment mode</label><select name="stages[${i}][assignment_mode]" class="form-control"><option value="ROLE">Any staff with role</option><option value="STAFF">Specific assigned staff</option><option value="DEPARTMENT_ROLE">Department + role</option></select></div><div class="form-group col-md-8"><label>Assigned staff</label><select name="stages[${i}][assigned_user_id]" class="form-control"><option value="">Use assignment mode</option>@foreach($staff as $member)<option value="{{ $member->id }}">{{ $member->fullname }} — {{ $member->email }}</option>@endforeach</select></div></div><div class="form-row"><div class="form-group col-md-4"><label><input type="checkbox" name="stages[${i}][is_final]" value="1"> Final stage</label></div><div class="form-group col-md-4"><label><input type="checkbox" name="stages[${i}][requires_placement]" value="1"> Requires placement</label></div><div class="form-group col-md-4"><label>Starting stage</label><select class="form-control start-stage"><option value="0">No</option><option value="1">Yes</option></select></div></div><div class="form-group mb-0"><label>Required duties</label><textarea name="stages[${i}][duties]" class="form-control" rows="4" placeholder="One duty per line"></textarea></div></div>`;stages.appendChild(r);reindex();}); document.getElementById('add-transition')?.addEventListener('click',()=>{const i=transitions.querySelectorAll('.transition-row').length,r=document.createElement('div');r.className='border rounded p-3 mb-3 transition-row';r.innerHTML=`<div class="form-row"><div class="form-group col-md-3"><label>From</label><select name="transitions[${i}][from_code]" class="form-control from">${options()}</select></div><div class="form-group col-md-3"><label>Action</label><select name="transitions[${i}][action]" class="form-control action">@foreach($actions as $key=>$action)<option value="{{ $key }}">{{ $action['label'] }}</option>@endforeach</select></div><div class="form-group col-md-3"><label>To</label><select name="transitions[${i}][to_code]" class="form-control to">${options()}</select></div><div class="form-group col-md-3"><label>Responsible role</label><select name="transitions[${i}][responsible_role_id]" class="form-control"><option value="">Stage role</option>@foreach($roles as $role)<option value="{{ $role->id }}">{{ $role->name }}</option>@endforeach</select></div></div><div class="form-row"><div class="form-group col-md-5"><label>Button label</label><input name="transitions[${i}][label]" class="form-control" value="Forward" required></div><div class="form-group col-md-4"><label>Result status</label><select name="transitions[${i}][result_status]" class="form-control">@foreach($resultStatuses as $key=>$label)<option value="{{ $key }}">{{ $label }}</option>@endforeach</select></div><div class="form-group col-md-3 pt-4"><label><input type="checkbox" name="transitions[${i}][requires_comment]" value="1"> Require comment</label></div></div><button type="button" class="btn btn-sm btn-outline-danger remove-transition">Remove action</button>`;transitions.appendChild(r);reindex();}); refresh();})();
</script>@endpush
